// Mirrorly - cable connections: Android phones over adb, iPhones over Personal Hotspot
#include "app.h"

#include <shlobj.h>

#include "log.h"

// RCDATA resources (see res/android.rc, generated by build_windows.sh)
enum { RES_ADB = 200, RES_ADB_WINAPI = 201, RES_ADB_WINUSB = 202, RES_SCRCPY_SERVER = 210 };

static std::vector<uint8_t> loadResource(int id) {
    HRSRC r = FindResourceW(nullptr, MAKEINTRESOURCEW(id), MAKEINTRESOURCEW(10) /* RT_RCDATA */);
    if (!r) return {};
    HGLOBAL g = LoadResource(nullptr, r);
    DWORD n = SizeofResource(nullptr, r);
    const uint8_t* p = g ? (const uint8_t*)LockResource(g) : nullptr;
    if (!p || !n) return {};
    return std::vector<uint8_t>(p, p + n);
}

// %LOCALAPPDATA%\Mirrorly\adb-<server version>
static std::wstring adbDir() {
    PWSTR base = nullptr;
    std::wstring dir;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_LocalAppData, 0, nullptr, &base)) && base) {
        dir = std::wstring(base) + L"\\Mirrorly";
        CoTaskMemFree(base);
    } else {
        dir = Settings::dataDir();
    }
    CreateDirectoryW(dir.c_str(), nullptr);
    dir += L"\\adb-" + from_utf8(mn::kScrcpyServerVersion);
    CreateDirectoryW(dir.c_str(), nullptr);
    return dir;
}

static bool writeIfChanged(const std::wstring& path, const std::vector<uint8_t>& data) {
    WIN32_FILE_ATTRIBUTE_DATA fa;
    if (GetFileAttributesExW(path.c_str(), GetFileExInfoStandard, &fa) && fa.nFileSizeHigh == 0 &&
        fa.nFileSizeLow == data.size())
        return true;
    std::wstring tmp = path + L".tmp";
    HANDLE f = CreateFileW(tmp.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (f == INVALID_HANDLE_VALUE) return false;
    DWORD wr = 0;
    bool ok = WriteFile(f, data.data(), (DWORD)data.size(), &wr, nullptr) && wr == data.size();
    CloseHandle(f);
    if (!ok || !MoveFileExW(tmp.c_str(), path.c_str(), MOVEFILE_REPLACE_EXISTING)) {
        DeleteFileW(tmp.c_str());
        return false;
    }
    return true;
}

// Unpacks the bundled adb and starts its server (no console window). Runs on the engine thread.
bool App::launchAdb() {
    std::vector<uint8_t> adb = loadResource(RES_ADB);
    if (adb.empty()) {
        mn::logf(mn::LogLevel::Warn, "android: adb is not bundled in this build");
        return false;
    }
    std::wstring dir = adbDir();
    if (!writeIfChanged(dir + L"\\adb.exe", adb) || !writeIfChanged(dir + L"\\AdbWinApi.dll", loadResource(RES_ADB_WINAPI)) ||
        !writeIfChanged(dir + L"\\AdbWinUsbApi.dll", loadResource(RES_ADB_WINUSB))) {
        mn::logf(mn::LogLevel::Error, "android: could not unpack adb to %s", to_utf8(dir).c_str());
        return false;
    }
    std::wstring exe = dir + L"\\adb.exe";
    std::wstring cmd = L"\"" + exe + L"\" start-server";
    STARTUPINFOW si{sizeof(si)};
    PROCESS_INFORMATION pi{};
    if (!CreateProcessW(exe.c_str(), &cmd[0], nullptr, nullptr, FALSE, CREATE_NO_WINDOW, nullptr, dir.c_str(), &si, &pi)) {
        mn::logf(mn::LogLevel::Error, "android: could not run adb (error %lu)", GetLastError());
        return false;
    }
    DWORD code = 1;
    if (WaitForSingleObject(pi.hProcess, 20000) == WAIT_OBJECT_0) GetExitCodeProcess(pi.hProcess, &code);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    if (code != 0) {
        mn::logf(mn::LogLevel::Error, "android: adb start-server failed (exit code %lu)", code);
        return false;
    }
    startedAdb_ = true;
    return true;
}

// Stops the adb server if Mirrorly started it (an adb that was already running is left alone).
void App::stopAdb() {
    if (startedAdb_.exchange(false)) mn::AdbClient().killServer();
}

mn::AndroidConfig App::androidConfig() const {
    mn::AndroidConfig c;
    c.enabled = settings_.usbAndroid || settings_.wifiAndroid;
    c.usb = settings_.usbAndroid;
    c.wireless = settings_.wifiAndroid;
    c.control = settings_.controlAndroid || settings_.gamepadAndroid;
    int w = 1920, h = 1080;
    settings_.resolutionSize(w, h);
    c.maxSize = std::max(w, h);
    c.maxFps = settings_.fps;
    c.audio = settings_.audio;
    c.videoBitRate = h >= 2160 ? 24000000 : h >= 1440 ? 16000000 : 12000000;
    return c;
}

void App::startAndroid() {
    android_.setServerJar(loadResource(RES_SCRCPY_SERVER));
    android_.setAdbLauncher([this]() { return launchAdb(); });
    android_.start(androidConfig(), this);
}

// An iPhone with Personal Hotspot on shows up as an "Apple Mobile Device Ethernet" adapter
// when plugged in; AirPlay then works over the cable like over Wi-Fi.
void App::checkUsbIphone() {
    bool found = false;
    for (auto& ni : mn::list_ipv4_interfaces())
        if (ni.description.find("Apple Mobile Device Ethernet") != std::string::npos) found = true;
    if (found != iphoneUsb_) {
        iphoneUsb_ = found;
        mn::logf(mn::LogLevel::Info, "usb: iPhone %s", found ? "connected by cable (Personal Hotspot)" : "cable disconnected");
        if (found && !sessionActive_) showToast(L"iPhone connected by cable. Use Screen Mirroring on the iPhone.");
        InvalidateRect(hwnd_, nullptr, FALSE);
    }
}
